import { inRange } from './stats_time_buckets';

interface TotalEntry {
    label: string;
    tooltip: string;
    value: number;
}

function isCountedConversation(conversation: StatsConversationFact, controls: StatsControls) {
    if (controls.totalsMetric === 'duration') {
        return TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
            && conversation.completedAt !== null
            && inRange(conversation.completedAt, controls);
    }
    if (!controls.startUtc && !controls.endUtc) return true;

    return conversation.completedAt !== null && inRange(conversation.completedAt, controls);
}

/** Ungrouped totals per card or action, accumulated in a single pass over conversations. */
export function totalsRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
    const cardsById = new Map(source.cards.map((card) => [card.internalId, card]));
    const totals = new Map<string, TotalEntry>();
    for (const conversation of source.stats.conversations.filter((fact) => isCountedConversation(fact, controls))) {
        const identity = controls.totalsGrouping === 'card' ? conversation.cardInternalId : conversation.actionId;
        if (!identity) continue;
        const display = controls.totalsGrouping === 'card'
            ? cardDisplay(identity, conversation.cardPath, cardsById)
            : { label: actionLabel(identity, conversation.actionLabel), tooltip: actionLabel(identity, conversation.actionLabel) };
        const value = controls.totalsMetric === 'duration' ? conversation.elapsedMs : conversation.totalTokens;
        if (value === null) continue;
        const current = totals.get(identity);
        totals.set(identity, { label: display.label, tooltip: display.tooltip, value: (current?.value ?? 0) + value });
    }
    const unit: StatsUnit = controls.totalsMetric === 'duration' ? 'milliseconds' : 'tokens';

    return [...totals.entries()]
        .map(([identity, { label, tooltip, value }]) => ({
            actionId: controls.totalsGrouping === 'action' ? identity : null,
            actionType: null,
            accessibleLabel: `${tooltip}: ${value} ${unit}`,
            agent: null,
            available: true,
            chartRole: 'primary',
            displayLabel: label,
            grouping: controls.totalsGrouping,
            identity,
            denominator: null,
            limitId: null,
            metric: controls.totalsMetric,
            numerator: null,
            provider: null,
            sampleCount: null,
            seriesIdentity: null,
            seriesLabel: null,
            stackIdentity: null,
            stackLabel: null,
            statusCounts: null,
            tooltip: `${tooltip}: ${value} ${unit}`,
            unit,
            utcBucketEnd: null,
            utcBucketStart: null,
            value,
            windowId: null,
        } satisfies StatsChartRow))
        .sort((left, right) => right.value - left.value || left.displayLabel.localeCompare(right.displayLabel));
}

import type { LoadedStatsSource, StatsControls, StatsOptions } from './project_stats_types';
import { accountSeriesIdentity, modelIdentity } from './stats_identities';

function optionList(entries: Array<[string, string]>) {
    return [...new Map(entries).entries()]
        .map(([identity, label]) => ({ identity, label }))
        .sort((left, right) => left.label.localeCompare(right.label) || left.identity.localeCompare(right.identity));
}

/** Derives the selectable action, agent, model, and account-series catalogs from one loaded source. */
export function buildOptions(source: LoadedStatsSource): StatsOptions {
    const attributed = source.stats.conversations.filter(({ agent, isRootConversation, model }) => isRootConversation && agent && model);
    const actions = optionList([
        ...source.stats.actions.map(({ actionId, actionLabel }) => [actionId, actionLabel] as [string, string]),
        ...source.stats.conversations.flatMap(({ actionId, actionLabel }) => (
            actionId ? [[actionId, actionLabel ?? actionId] as [string, string]] : []
        )),
    ]);
    const agents = optionList(attributed.map(({ agent }) => [agent!, agent!]));
    const models = optionList(attributed.map(({ agent, model }) => [modelIdentity(agent!, model!), `${agent} - ${model}`]));
    const accountSeries = [...new Map(source.accountRows.map((row) => [accountSeriesIdentity(row), {
        identity: accountSeriesIdentity(row),
        limitId: row.limitId,
        provider: row.provider,
        windowDurationMinutes: row.windowDurationMinutes,
        windowId: row.windowId,
    }])).values()].sort((left, right) => left.identity.localeCompare(right.identity));

    return { accountSeries, actions, agents, models };
}

function retainValidSelections(selected: string[], available: Set<string>) {
    return selected.filter((identity) => available.has(identity));
}

/** Drops entity selections that the freshly loaded source no longer offers. */
export function reconcileControls(controls: StatsControls, options: StatsOptions): StatsControls {
    return {
        ...controls,
        performanceActionIds: retainValidSelections(
            controls.performanceActionIds,
            new Set(options.actions.map(({ identity }) => identity)),
        ),
        performanceAgentIds: retainValidSelections(controls.performanceAgentIds, new Set(options.agents.map(({ identity }) => identity))),
        performanceModelIds: retainValidSelections(controls.performanceModelIds, new Set(options.models.map(({ identity }) => identity))),
    };
}

import type { StatsActionFact } from '../../../../shared/project_stats.mjs';
import type { UsageMetricsTokenRow } from '../agents/project_usage_metrics_service';
import type { LoadedStatsSource, StatsChartRow, StatsControls, StatsGranularity } from './project_stats_types';
import { emptyTimeRow } from './stats_chart_rows';
import { actionLabel } from './stats_identities';
import { bucketContexts, bucketDomain, inRange, indexByBucket, type StatsBucketContext } from './stats_time_buckets';

interface ActionCount {
    label: string;
    value: number;
}

function actionCountRows(
    context: StatsBucketContext,
    granularity: StatsGranularity,
    records: StatsActionFact[],
): StatsChartRow[] {
    if (records.length === 0) return [emptyTimeRow(context, granularity, 'primary', 'actions', 'actions')];
    const counts = new Map<string, ActionCount>();
    for (const record of records) {
        const current = counts.get(record.actionId);
        counts.set(record.actionId, { label: actionLabel(record.actionId, record.actionLabel), value: (current?.value ?? 0) + 1 });
    }
    const total = records.length;

    return [...counts.entries()].sort(([left], [right]) => left.localeCompare(right)).map(([identity, count]) => {
        const tooltip = `${context.localLabel}; UTC ${context.interval}; total ${total} actions; ${count.label}: ${count.value}`;

        return {
            ...emptyTimeRow(context, granularity, 'primary', 'actions', 'actions'),
            actionId: identity,
            accessibleLabel: tooltip,
            identity,
            seriesIdentity: identity,
            seriesLabel: count.label,
            stackIdentity: identity,
            tooltip,
            value: count.value,
        } satisfies StatsChartRow;
    });
}

function distinctCardRow(context: StatsBucketContext, granularity: StatsGranularity, records: StatsActionFact[]): StatsChartRow {
    const count = new Set(records.flatMap(({ cardInternalId }) => cardInternalId ? [cardInternalId] : [])).size;
    const tooltip = `${context.localLabel}; UTC ${context.interval}; ${count} cards`;

    return {
        ...emptyTimeRow(context, granularity, 'primary', 'cards', 'cards'),
        accessibleLabel: tooltip,
        tooltip,
        value: count,
    };
}

function tokenTotalRow(context: StatsBucketContext, granularity: StatsGranularity, rows: UsageMetricsTokenRow[]): StatsChartRow {
    const value = rows.reduce((total, row) => total + row.totalTokens, 0);
    const tooltip = `${context.localLabel}; UTC ${context.interval}; ${value} tokens`;

    return { ...emptyTimeRow(context, granularity, 'primary', 'tokens', 'tokens'), accessibleLabel: tooltip, tooltip, value };
}

/** Zero-filled activity per UTC bucket, counted from a single bucket index instead of a scan per bucket. */
export function activityRows(source: LoadedStatsSource, controls: StatsControls, granularity: StatsGranularity): StatsChartRow[] {
    const metric = controls.activityMetric;
    const actionRecords = source.stats.actions.filter(({ completedAt }) => inRange(completedAt, controls));
    const tokenRows = source.tokenRows.filter(({ recordedAt }) => inRange(recordedAt, controls));
    const timestamps = metric === 'tokens'
        ? tokenRows.map(({ recordedAt }) => recordedAt)
        : actionRecords.map(({ completedAt }) => completedAt);
    const contexts = bucketContexts(bucketDomain(timestamps, granularity, controls), granularity);
    if (metric === 'tokens') {
        const tokensByBucket = indexByBucket(tokenRows, granularity, ({ recordedAt }) => recordedAt);

        return contexts.map((context) => tokenTotalRow(context, granularity, tokensByBucket.get(context.start) ?? []));
    }
    const actionsByBucket = indexByBucket(actionRecords, granularity, ({ completedAt }) => completedAt);
    if (metric === 'cards') {
        return contexts.map((context) => distinctCardRow(context, granularity, actionsByBucket.get(context.start) ?? []));
    }

    return contexts.flatMap((context) => actionCountRows(context, granularity, actionsByBucket.get(context.start) ?? []));
}

